// Package gitleaksrules scans unified diffs with the gitleaks default ruleset
// embedded in the gk binary, so secret scanning works without the gitleaks
// binary installed.
//
// rules.json is generated by tools/genrules from a pinned gitleaks release
// (see `make gen-rules`). The engine mirrors the gitleaks detection steps
// that the default config relies on: keyword prefilter, regex, secret group,
// entropy, path rules, and global and per-rule allowlists.
package gitleaksrules

import (
	"cmp"
	_ "embed"
	"encoding/json"
	"math"
	"regexp"
	"regexp/syntax"
	"runtime"
	"slices"
	"sort"
	"strconv"
	"strings"
	"sync"
	"sync/atomic"
	"unicode"
	"unicode/utf8"

	"github.com/x-mesh/gk/internal/secrets"
	"github.com/x-mesh/gk/internal/secrets/gitleaksrules/codec"
)

//go:embed rules.json
var rulesJSON []byte

type ruleset struct {
	Source    source     `json:"source"`
	Allowlist allowlist  `json:"allowlist"`
	Rules     []jsonRule `json:"rules"`
}

type source struct {
	GitleaksVersion string `json:"gitleaksVersion"`
}

type allowlist struct {
	Paths     []string `json:"paths"`
	Regexes   []string `json:"regexes"`
	Stopwords []string `json:"stopwords"`
}

type jsonRule struct {
	ID          string          `json:"id"`
	Regex       string          `json:"regex"`
	Path        string          `json:"path"`
	Keywords    []string        `json:"keywords"`
	Entropy     float64         `json:"entropy"`
	SecretGroup int             `json:"secretGroup"`
	Allowlists  []jsonRuleAllow `json:"allowlists"`
}

type jsonRuleAllow struct {
	Condition   string   `json:"condition"`
	RegexTarget string   `json:"regexTarget"`
	Regexes     []string `json:"regexes"`
	Paths       []string `json:"paths"`
	Stopwords   []string `json:"stopwords"`
}

type ruleAllow struct {
	and       bool
	target    string
	regexes   []*regexp.Regexp
	paths     []*regexp.Regexp
	stopwords []string
}

type rule struct {
	id          string
	regex       *regexp.Regexp
	path        *regexp.Regexp
	keywordIDs  []int32
	entropy     float64
	secretGroup int
	allowlists  []ruleAllow
	// windowed is set when a decoded pass may search only the windows
	// around its segments; see windowable.
	windowed bool
	// keywords are the lower-case keywords of the rule, and anchorLen is
	// its longest match in bytes when the raw text may be searched only
	// around those keywords, 0 otherwise; see anchorLength.
	keywords  []string
	anchorLen int
}

type engine struct {
	version         string
	globalPaths     []*regexp.Regexp
	globalRegexes   []*regexp.Regexp
	globalStopwords []string
	rules           []rule
	gkRules         int
	keywords        *keywordMatcher
}

var (
	loadOnce sync.Once
	loaded   *engine
)

// Version returns the gitleaks release the embedded ruleset came from.
func Version() string { return get().version }

// RuleCount returns the number of embedded gitleaks rules.
func RuleCount() int { return len(get().rules) - get().gkRules }

// GKRuleCount returns the number of rules that gk adds to the gitleaks
// ruleset.
func GKRuleCount() int { return get().gkRules }

// get compiles the ruleset on first use so commands that never scan do not
// pay for compiling hundreds of regexes.
func get() *engine {
	loadOnce.Do(func() {
		var rs ruleset
		if err := json.Unmarshal(rulesJSON, &rs); err != nil {
			panic("gitleaksrules: corrupt embedded rules.json: " + err.Error())
		}
		rs.Rules = append(rs.Rules, gkRules...)
		loaded = compile(rs)
		loaded.gkRules = len(gkRules)
	})
	return loaded
}

// mustCompile panics on a bad pattern: genrules already rejected every
// pattern, so a failure here means the embedded file was altered by hand.
func mustCompile(p string) *regexp.Regexp {
	if p == "" {
		return nil
	}
	return regexp.MustCompile(p)
}

func mustCompileAll(ps []string) []*regexp.Regexp {
	out := make([]*regexp.Regexp, 0, len(ps))
	for _, p := range ps {
		out = append(out, regexp.MustCompile(p))
	}
	return out
}

func lowerAll(ss []string) []string {
	out := make([]string, len(ss))
	for i, s := range ss {
		out[i] = strings.ToLower(s)
	}
	return out
}

func compile(rs ruleset) *engine {
	e := &engine{
		version:         rs.Source.GitleaksVersion,
		globalPaths:     mustCompileAll(rs.Allowlist.Paths),
		globalRegexes:   mustCompileAll(rs.Allowlist.Regexes),
		globalStopwords: lowerAll(rs.Allowlist.Stopwords),
	}
	var words []string
	wordID := map[string]int32{}
	for _, jr := range rs.Rules {
		r := rule{
			id:          jr.ID,
			regex:       mustCompile(jr.Regex),
			path:        mustCompile(jr.Path),
			entropy:     jr.Entropy,
			secretGroup: jr.SecretGroup,
			windowed:    windowable(jr.Regex),
			keywords:    lowerAll(jr.Keywords),
		}
		r.anchorLen = anchorLength(jr.Regex, r.keywords)
		for _, kw := range r.keywords {
			id, ok := wordID[kw]
			if !ok {
				id = int32(len(words))
				wordID[kw] = id
				words = append(words, kw)
			}
			r.keywordIDs = append(r.keywordIDs, id)
		}
		for _, ja := range jr.Allowlists {
			r.allowlists = append(r.allowlists, ruleAllow{
				and:       ja.Condition == "AND",
				target:    ja.RegexTarget,
				regexes:   mustCompileAll(ja.Regexes),
				paths:     mustCompileAll(ja.Paths),
				stopwords: lowerAll(ja.Stopwords),
			})
		}
		e.rules = append(e.rules, r)
	}
	e.keywords = newKeywordMatcher(words)
	return e
}

// ScanDiff scans the added lines of a unified diff (`git diff` or
// `git log -p` output) and returns one finding per matched secret.
func ScanDiff(diff string) []secrets.Finding { return get().scanDiff(diff) }

func (e *engine) scanDiff(diff string) []secrets.Finding { return e.scanFiles(parseDiff(diff)) }

// ScanFile scans the whole content of one file, the unit gitleaks scans in
// dir mode. FileLine counts from the first line of content.
func ScanFile(path, content string) []secrets.Finding {
	h := hunk{lines: strings.Split(strings.TrimSuffix(content, "\n"), "\n")}
	h.numbers = make([]int, len(h.lines))
	for i := range h.numbers {
		h.numbers[i] = i + 1
	}
	h.joined = strings.Join(h.lines, "\n")
	h.lower = strings.ToLower(h.joined)
	return get().scanFiles([]fileDiff{{path: path, hunks: []hunk{h}}})
}

// splitBytes is the scanned size above which one file is spread over several
// workers. Per-rule cost is roughly even, so splitting the rule list balances
// a large file (the embedded rules.json alone took 0.8s on one core).
const splitBytes = 8 << 10

// unitKind is the work a scanUnit does on its file.
type unitKind int

const (
	decodeUnit  unitKind = iota // decodes the file's hunks
	rawUnit                     // applies rules to the raw passes
	decodedUnit                 // applies rules to the decoded passes
)

// scanUnit is one piece of work on one file: decoding it, or applying one
// slice of the rule list to its raw or decoded passes.
type scanUnit struct {
	kind  unitKind
	file  int
	rules []rule
	hits  []hit
}

// hit is a finding plus its unmasked secret, which the generic-rule filter
// compares. The secret never leaves the engine.
type hit struct {
	secrets.Finding
	secret string
}

// decodedLag is how many worker counts of units sit between a file's raw
// units and its decoded units in the queue. With a lag of one, decoded units
// often waited for their file's decoding to finish (40.0s against 36.3s on a
// 137 MB history diff).
const decodedLag = 16

// scanFiles scans files concurrently and returns findings in file order, so
// a report is identical between runs.
//
// Each file queues its decode unit ahead of its raw units, and its decoded
// units decodedLag worker counts of units after its raw units. A worker
// decodes while the others scan raw text, and a decoded unit rarely waits:
// when each split unit waited for its file's decoding, the idle workers added
// a third to the wall time. The last decoded unit of a file frees its decoded
// passes, so only the files inside that lag hold decoded copies at once.
func (e *engine) scanFiles(files []fileDiff) []secrets.Finding {
	workers := runtime.GOMAXPROCS(0)
	type heldUnits struct {
		releaseAt int // queue length at which the units join the queue
		units     []scanUnit
	}
	var units []scanUnit
	var held []heldUnits
	release := func(all bool) {
		for len(held) > 0 && (all || len(units) >= held[0].releaseAt) {
			units = append(units, held[0].units...)
			held = held[1:]
		}
	}
	decodedLeft := make([]atomic.Int32, len(files))
	for i, f := range files {
		if e.pathSkipped(f.path) {
			continue
		}
		size := 0
		for _, h := range f.hunks {
			size += len(h.joined)
		}
		units = append(units, scanUnit{kind: decodeUnit, file: i})
		chunks := min(workers, 1+size/splitBytes)
		per := (len(e.rules) + chunks - 1) / chunks
		var decoded []scanUnit
		for lo := 0; lo < len(e.rules); lo += per {
			rules := e.rules[lo:min(lo+per, len(e.rules))]
			units = append(units, scanUnit{kind: rawUnit, file: i, rules: rules})
			decoded = append(decoded, scanUnit{kind: decodedUnit, file: i, rules: rules})
		}
		decodedLeft[i].Store(int32(len(decoded)))
		held = append(held, heldUnits{releaseAt: len(units) + decodedLag*workers, units: decoded})
		release(false)
	}
	release(true)

	// The keyword pass of the raw text runs once per file, by whichever raw
	// unit of the file starts first; the other units of a split file reuse it.
	type filePasses struct {
		rawOnce sync.Once
		raw     []pass
		decoded [][]pass
		ready   chan struct{}
	}
	prepared := make([]filePasses, len(files))
	for i := range prepared {
		prepared[i].ready = make(chan struct{})
	}

	var next atomic.Int64
	var wg sync.WaitGroup
	for range min(workers, len(units)) {
		wg.Go(func() {
			for {
				i := int(next.Add(1)) - 1
				if i >= len(units) {
					return
				}
				u := &units[i]
				fp := &prepared[u.file]
				f := files[u.file]
				switch u.kind {
				case decodeUnit:
					fp.decoded = e.decodedPasses(f)
					close(fp.ready)
				case rawUnit:
					fp.rawOnce.Do(func() { fp.raw = e.rawPasses(f) })
					u.hits = e.scanRaw(f, u.rules, fp.raw)
				case decodedUnit:
					// The decode unit is ahead in the queue, so a worker
					// already holds it and this wait ends.
					<-fp.ready
					u.hits = e.scanDecoded(f, u.rules, fp.decoded)
					if decodedLeft[u.file].Add(-1) == 0 {
						fp.decoded = nil
					}
				}
			}
		})
	}
	wg.Wait()

	fileHits := make([][]hit, len(files))
	for _, u := range units {
		fileHits[u.file] = append(fileHits[u.file], u.hits...)
	}
	var out []secrets.Finding
	for i, hs := range fileHits {
		// pathSkipped runs the global path regexes, so the cheap test of
		// the extension goes first.
		if isYAML(files[i].path) && !e.pathSkipped(files[i].path) {
			hs = e.withYAMLPaths(files[i], hs)
		}
		out = append(out, dropShadowedGeneric(hs)...)
	}
	return out
}

func (e *engine) scanFile(f fileDiff) []secrets.Finding {
	if e.pathSkipped(f.path) {
		return nil
	}
	hs := e.scanRaw(f, e.rules, e.rawPasses(f))
	hs = append(hs, e.scanDecoded(f, e.rules, e.decodedPasses(f))...)
	return dropShadowedGeneric(e.withYAMLPaths(f, hs))
}

// pathSkipped reports whether the global allowlist skips the file at p. For
// a file inside an archive (app.zip!node_modules/x.js) gitleaks also matches
// the path inside the archive on its own, so a pattern anchored at the start
// of a path, such as (?:^|/)node_modules/, applies there too.
func (e *engine) pathSkipped(p string) bool {
	if p == "" || matchAny(e.globalPaths, p) {
		return true
	}
	for i := 0; i < len(p); i++ {
		if strings.HasPrefix(p[i:], secrets.ArchiveSeparator) && secrets.IsZipArchive(p[:i]) {
			return matchAny(e.globalPaths, p[i+len(secrets.ArchiveSeparator):])
		}
	}
	return false
}

// maxDecodeDepth is the gitleaks default for --max-decode-depth.
const maxDecodeDepth = 5

// decodeWindowMargin is how far around its decoded segments a decoded pass is
// searched. A decoded pass matters only where a match touches a segment, and
// searching only there instead of the whole hunk cut a bundle-heavy repo's
// decoding cost about tenfold. Rules whose matches can be longer than half
// the margin search the whole decoded text instead.
const decodeWindowMargin = 16 << 10

// windowable reports whether no match of pattern is longer than half of
// decodeWindowMargin. A match that touches a segment then starts inside the
// segment's window, and a match that starts before the window ends before it
// reaches one that touches the segment. This is a limit, not a proof of equal
// results: a run of overlapping matches that crosses the window start can
// still shift which matches the window search reports.
func windowable(pattern string) bool {
	if pattern == "" {
		return false
	}
	re, err := syntax.Parse(pattern, syntax.Perl)
	if err != nil {
		return false
	}
	n := maxMatchBytes(re)
	return n >= 0 && 2*n <= decodeWindowMargin
}

// maxMatchBytes returns the longest match of re in bytes, or -1 when its
// length has no bound.
func maxMatchBytes(re *syntax.Regexp) int {
	switch re.Op {
	case syntax.OpLiteral:
		n := 0
		for _, r := range re.Rune {
			n += runeBytes(r, re.Flags&syntax.FoldCase != 0)
		}
		return n
	case syntax.OpCharClass:
		// The ranges ascend, so the last one ends at the widest rune.
		if len(re.Rune) == 0 {
			return 0
		}
		return runeBytes(re.Rune[len(re.Rune)-1], false)
	case syntax.OpAnyChar, syntax.OpAnyCharNotNL:
		return utf8.UTFMax
	case syntax.OpCapture, syntax.OpQuest:
		return maxMatchBytes(re.Sub[0])
	case syntax.OpStar, syntax.OpPlus:
		return -1
	case syntax.OpRepeat:
		n := maxMatchBytes(re.Sub[0])
		if re.Max < 0 || n < 0 {
			return -1
		}
		return n * re.Max
	case syntax.OpConcat, syntax.OpAlternate:
		total := 0
		for _, sub := range re.Sub {
			n := maxMatchBytes(sub)
			if n < 0 {
				return -1
			}
			if re.Op == syntax.OpConcat {
				total += n
			} else {
				total = max(total, n)
			}
		}
		return total
	}
	// Anchors, word boundaries, and empty matches consume no text.
	return 0
}

// runeBytes returns the most bytes a literal rune can match. Under case
// folding that is the widest rune of its fold orbit: `(?i)k` also matches
// the three-byte Kelvin sign U+212A.
func runeBytes(r rune, fold bool) int {
	n := utf8.RuneLen(r)
	if fold {
		for f := unicode.SimpleFold(r); f != r; f = unicode.SimpleFold(f) {
			n = max(n, utf8.RuneLen(f))
		}
	}
	if n < 0 {
		return utf8.UTFMax
	}
	return n
}

// pass is one decoding pass over a hunk: the text the rules run on, the
// rule keywords it contains, the segments this pass decoded (none for the
// raw text), and the windows of text around those segments to search. The
// raw pass also holds the lower-case text and whether anchored rules may
// search it by keyword position; see anchorSafe.
type pass struct {
	text     string
	keywords keywordSet
	segments []*codec.EncodedSegment
	windows  [][2]int
	lower    string
	anchorOK bool
}

// rawPasses returns the undecoded pass of each hunk.
func (e *engine) rawPasses(f fileDiff) []pass {
	out := make([]pass, len(f.hunks))
	for i, h := range f.hunks {
		out[i] = pass{text: h.joined, keywords: e.findKeywords(h.lower), lower: h.lower, anchorOK: anchorSafe(h.joined)}
	}
	return out
}

// decodedPasses returns, per hunk, up to maxDecodeDepth passes that decode
// base64, hex, percent, and unicode escapes in place, as gitleaks does for
// every fragment.
func (e *engine) decodedPasses(f fileDiff) [][]pass {
	out := make([][]pass, len(f.hunks))
	for i, h := range f.hunks {
		decoder := codec.NewDecoder()
		text, segments := h.joined, []*codec.EncodedSegment{}
		for range maxDecodeDepth {
			text, segments = decoder.Decode(text, segments)
			if len(segments) == 0 {
				break
			}
			out[i] = append(out[i], pass{
				text:     text,
				keywords: e.findKeywords(strings.ToLower(text)),
				segments: segments,
				windows:  segmentWindows(segments, len(text)),
			})
		}
	}
	return out
}

// segmentWindows returns the merged ranges that cover each segment plus
// decodeWindowMargin on both sides, clamped to the text.
func segmentWindows(segments []*codec.EncodedSegment, textLen int) [][2]int {
	ranges := make([][2]int, 0, len(segments))
	for _, s := range segments {
		start, end := s.DecodedRange()
		ranges = append(ranges, [2]int{max(0, start-decodeWindowMargin), min(textLen, end+decodeWindowMargin)})
	}
	slices.SortFunc(ranges, func(a, b [2]int) int { return cmp.Compare(a[0], b[0]) })
	var out [][2]int
	for _, r := range ranges {
		if n := len(out); n > 0 && r[0] <= out[n-1][1] {
			out[n-1][1] = max(out[n-1][1], r[1])
			continue
		}
		out = append(out, r)
	}
	return out
}

// passMatches returns the rule's matches in a pass. In the raw pass an
// anchored rule searches only around its keywords. In a decoded pass a
// windowed rule searches only the windows; a match that reaches a window edge
// inside the text may be cut short or exist only because of the cut (`^`, `$`,
// `\b`), so the whole text is searched instead.
func passMatches(r rule, p pass) [][]int {
	if len(p.segments) == 0 && r.anchorLen > 0 && p.anchorOK {
		return anchoredMatches(r, p)
	}
	if p.windows == nil || !r.windowed {
		return r.regex.FindAllStringSubmatchIndex(p.text, -1)
	}
	var out [][]int
	for _, w := range p.windows {
		for _, loc := range r.regex.FindAllStringSubmatchIndex(p.text[w[0]:w[1]], -1) {
			if (loc[0] == 0 && w[0] > 0) || (loc[1] == w[1]-w[0] && w[1] < len(p.text)) {
				return r.regex.FindAllStringSubmatchIndex(p.text, -1)
			}
			for i := range loc {
				if loc[i] >= 0 {
					loc[i] += w[0]
				}
			}
			out = append(out, loc)
		}
	}
	return out
}

func (e *engine) findKeywords(lower string) keywordSet {
	seen := e.keywords.newSet()
	e.keywords.find(lower, seen)
	return seen
}

// scanRaw applies the rules to the raw pass of every hunk.
func (e *engine) scanRaw(f fileDiff, rules []rule, raw []pass) []hit {
	var out []hit
	for _, r := range rules {
		if r.path != nil && !r.path.MatchString(f.path) {
			continue
		}
		if r.regex == nil {
			// gitleaks reports a path-only match at line 0.
			out = append(out, hit{Finding: secrets.Finding{Kind: r.id, File: f.path}})
			continue
		}
		for i, h := range f.hunks {
			if hasKeyword(r, raw[i].keywords) {
				out = append(out, e.scanPass(r, f.path, h, raw[i])...)
			}
		}
	}
	return out
}

// scanDecoded applies the regex rules to the decoded passes of every hunk.
func (e *engine) scanDecoded(f fileDiff, rules []rule, decoded [][]pass) []hit {
	var out []hit
	for _, r := range rules {
		if r.regex == nil || (r.path != nil && !r.path.MatchString(f.path)) {
			continue
		}
		for i, h := range f.hunks {
			for _, p := range decoded[i] {
				if hasKeyword(r, p.keywords) {
					out = append(out, e.scanPass(r, f.path, h, p)...)
				}
			}
		}
	}
	return out
}

const (
	genericRuleID    = "generic-api-key"
	awsAccessRuleID  = "aws-access-token"
	privateKeyRuleID = "private-key"
)

// dropShadowedGeneric removes a generic finding when a specific rule matched
// on the same line and its secret contains the generic secret. This follows
// filter() in gitleaks v8.30.1 detect/utils.go; a specific match of another
// secret on the line does not hide the generic one.
func dropShadowedGeneric(hs []hit) []secrets.Finding {
	specific := map[int][]hit{}
	for _, h := range hs {
		if !isGeneric(h.Kind) {
			specific[h.FileLine] = append(specific[h.FileLine], h)
		}
	}
	out := make([]secrets.Finding, 0, len(hs))
	for _, h := range hs {
		if !isGeneric(h.Kind) || !shadowed(h, specific[h.FileLine]) {
			out = append(out, h.Finding)
		}
	}
	return out
}

// shadowed reports whether a specific hit on the generic hit's line holds
// the generic secret.
func shadowed(g hit, sameLine []hit) bool {
	for _, s := range sameLine {
		if strings.Contains(s.secret, g.secret) {
			return true
		}
	}
	return false
}

func isGeneric(id string) bool { return strings.Contains(strings.ToLower(id), "generic") }

// scanPass applies one rule to one pass of a hunk. A match in a decoded pass
// counts only when it touches text decoded in that pass; earlier passes
// already reported the rest. Its location maps back to the raw hunk.
func (e *engine) scanPass(r rule, path string, h hunk, p pass) []hit {
	text := p.text
	var out []hit
	for _, loc := range passMatches(r, p) {
		match := text[loc[0]:loc[1]]
		span := loc[:2]
		allowLine := ""
		if len(p.segments) > 0 {
			segments := codec.SegmentsWithDecodedOverlap(p.segments, loc[0], loc[1])
			if len(segments) == 0 {
				continue
			}
			span = codec.AdjustMatchIndex(segments, span)
			allowLine = codec.CurrentLine(segments, text)
		}
		if allowedInline(h.joined, span) {
			continue
		}
		secretStart, secretEnd := secretSpan(loc, r.secretGroup)
		secret := text[secretStart:secretEnd]
		if r.entropy > 0 && shannon(secret) < r.entropy {
			continue
		}
		line := h.lineAt(span[0])
		if allowLine == "" {
			allowLine = h.lineText(line)
		}
		if e.allowed(r, path, secret, match, allowLine) {
			continue
		}
		f := secrets.Finding{
			Kind:     r.id,
			File:     path,
			FileLine: h.fileLine(line),
			Line:     h.fileLine(line),
			Sample:   maskSecret(secret),
		}
		switch r.id {
		case awsAccessRuleID:
			lines, idx := h.lines, line
			if len(p.segments) > 0 {
				// An encoded key ID usually sits beside an encoded secret,
				// as in the data of a Kubernetes Secret, so the pair is
				// searched in the decoded text.
				lines = strings.Split(text, "\n")
				idx = strings.Count(text[:secretStart], "\n")
			}
			f.Credential = secrets.PairAWS(lines, idx, secret)
		case privateKeyRuleID:
			f.Credential = secrets.KeyCandidate(secret)
		default:
			lineStart := strings.LastIndexByte(text[:secretStart], '\n') + 1
			lineEnd := len(text)
			if i := strings.IndexByte(text[secretStart:], '\n'); i >= 0 {
				lineEnd = secretStart + i
			}
			f.Credential = secrets.TokenCredential(r.id, text[lineStart:lineEnd], secretStart-lineStart, secret)
		}
		out = append(out, hit{Finding: f, secret: secret})
	}
	return out
}

// gitleaksAllow is the inline marker gitleaks honors on the matched lines.
const gitleaksAllow = "gitleaks:allow"

// allowedInline reports whether the lines spanned by a match carry the
// gitleaks:allow marker.
func allowedInline(text string, loc []int) bool {
	start := strings.LastIndexByte(text[:loc[0]], '\n') + 1
	end := len(text)
	if i := strings.IndexByte(text[loc[1]:], '\n'); i >= 0 {
		end = loc[1] + i
	}
	return strings.Contains(text[start:end], gitleaksAllow)
}

// secretSpan follows the gitleaks rule: an explicit secretGroup wins, then the
// first non-empty capture group, then the whole match. It returns the
// secret's byte range in the scanned text.
func secretSpan(loc []int, group int) (start, end int) {
	if group > 0 && 2*group+1 < len(loc) && loc[2*group] >= 0 {
		return loc[2*group], loc[2*group+1]
	}
	for g := 1; 2*g+1 < len(loc); g++ {
		if loc[2*g] >= 0 && loc[2*g] != loc[2*g+1] {
			return loc[2*g], loc[2*g+1]
		}
	}
	return loc[0], loc[1]
}

func (e *engine) allowed(r rule, path, secret, match, line string) bool {
	if matchAny(e.globalRegexes, secret) || hasStopword(e.globalStopwords, secret) {
		return true
	}
	for _, a := range r.allowlists {
		if a.allows(path, secret, match, line) {
			return true
		}
	}
	return false
}

func (a ruleAllow) allows(path, secret, match, line string) bool {
	target := secret
	switch a.target {
	case "match":
		target = match
	case "line":
		target = line
	}
	var results []bool
	if len(a.paths) > 0 {
		results = append(results, matchAny(a.paths, path))
	}
	if len(a.regexes) > 0 {
		results = append(results, matchAny(a.regexes, target))
	}
	if len(a.stopwords) > 0 {
		results = append(results, hasStopword(a.stopwords, secret))
	}
	if len(results) == 0 {
		return false
	}
	for _, ok := range results {
		if a.and && !ok {
			return false
		}
		if !a.and && ok {
			return true
		}
	}
	return a.and
}

func matchAny(res []*regexp.Regexp, s string) bool {
	for _, re := range res {
		if re.MatchString(s) {
			return true
		}
	}
	return false
}

func hasStopword(lowerWords []string, s string) bool {
	l := strings.ToLower(s)
	for _, w := range lowerWords {
		if strings.Contains(l, w) {
			return true
		}
	}
	return false
}

// hasKeyword is the gitleaks keyword prefilter: a rule with keywords runs
// its regex only on a hunk that contains one of them, case-insensitively.
func hasKeyword(r rule, seen keywordSet) bool {
	if len(r.keywordIDs) == 0 {
		return true
	}
	for _, id := range r.keywordIDs {
		if seen.has(id) {
			return true
		}
	}
	return false
}

func shannon(s string) float64 {
	if s == "" {
		return 0
	}
	freq := map[rune]float64{}
	n := 0.0
	for _, r := range s {
		freq[r]++
		n++
	}
	var h float64
	for _, c := range freq {
		p := c / n
		h -= p * math.Log2(p)
	}
	return h
}

func maskSecret(s string) string {
	if len(s) <= 4 {
		return strings.Repeat("*", len(s))
	}
	stars := min(len(s)-4, 8)
	return s[:4] + strings.Repeat("*", stars)
}

type fileDiff struct {
	path  string
	hunks []hunk
}

// hunk holds the added lines of one @@ hunk. gitleaks scans the same unit:
// added lines of a hunk joined by newlines.
type hunk struct {
	lines   []string
	numbers []int
	joined  string
	lower   string
}

// lineAt maps a byte offset in the joined text to an index into lines.
func (h hunk) lineAt(offset int) int {
	pos := 0
	starts := make([]int, len(h.lines))
	for i, l := range h.lines {
		starts[i] = pos
		pos += len(l) + 1
	}
	return sort.Search(len(starts), func(i int) bool { return starts[i] > offset }) - 1
}

func (h hunk) lineText(i int) string {
	if i < 0 || i >= len(h.lines) {
		return ""
	}
	return h.lines[i]
}

func (h hunk) fileLine(i int) int {
	if i < 0 || i >= len(h.numbers) {
		return 0
	}
	return h.numbers[i]
}

var hunkHeader = regexp.MustCompile(`^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@`)

// parseDiff splits a unified diff into per-file added-line hunks. A file with
// no added lines (a binary file or a pure rename) is still returned so
// path-only rules such as pkcs12-file can match it.
func parseDiff(diff string) []fileDiff {
	var files []fileDiff
	var cur *fileDiff
	var h *hunk
	newLine := 0
	flush := func() {
		if h != nil && len(h.lines) > 0 && cur != nil {
			h.joined = strings.Join(h.lines, "\n")
			h.lower = strings.ToLower(h.joined)
			cur.hunks = append(cur.hunks, *h)
		}
		h = nil
	}
	for line := range strings.SplitSeq(diff, "\n") {
		switch {
		case strings.HasPrefix(line, "diff --git "):
			flush()
			files = append(files, fileDiff{path: pathFromGitHeader(line)})
			cur = &files[len(files)-1]
		case cur == nil:
		case strings.HasPrefix(line, "+++ "):
			rest := line[len("+++ "):]
			if rest == "/dev/null" {
				cur.path = ""
			} else if p, ok := postImagePath(rest); ok {
				cur.path = p
			}
		case strings.HasPrefix(line, "@@"):
			flush()
			if m := hunkHeader.FindStringSubmatch(line); m != nil {
				newLine, _ = strconv.Atoi(m[1])
				h = &hunk{}
			}
		case h == nil:
		case strings.HasPrefix(line, "+"):
			h.lines = append(h.lines, line[1:])
			h.numbers = append(h.numbers, newLine)
			newLine++
		case strings.HasPrefix(line, " "):
			newLine++
		}
	}
	flush()
	return files
}

func pathFromGitHeader(line string) string {
	if i := strings.LastIndex(line, ` "b/`); i >= 0 {
		p, _ := postImagePath(line[i+1:])
		return p
	}
	if i := strings.LastIndex(line, " b/"); i >= 0 {
		return line[i+3:]
	}
	return ""
}

// postImagePath extracts the file path from a `b/<path>` header token. Git
// wraps a name that holds a quote, backslash, control character, or (with
// core.quotePath) non-ASCII byte in a C-style quoted string, and it appends a
// tab to an unquoted name that holds a space. Skipping a quoted name would
// silently drop that file from the scan.
func postImagePath(token string) (string, bool) {
	if strings.HasPrefix(token, `"`) {
		unq, err := strconv.Unquote(token)
		if err != nil {
			return "", false
		}
		token = unq
	} else {
		token = strings.TrimRight(token, "\t")
	}
	return strings.CutPrefix(token, "b/")
}
